ledger.record("a", "eng", "m", 10, 20)
try:
    ledger.record("b", "eng", "m2", 15, 22)
except (ValueError, AssertionError):
    pass
else:
    assert False
assert ledger.record("c", "eng", "m2", 20, 23) is True
for args in (("eng", 8, 7),):
    try:
        ledger.engine_flight_time(*args)
    except (TypeError, ValueError, AssertionError):
        pass
    else:
        assert False
for call in (
    lambda: ledger.engine_flight_time("missing"),
    lambda: ledger.mission_flight_time("missing"),
):
    try:
        call()
    except (KeyError, AssertionError):
        pass
    else:
        assert False
